INSERT INTO `cms_texts` (`text_key`, `text_value`) VALUES ('hero_description', 'SIREN menyajikan visualisasi spasial berbasis peta interaktif dan matriks perencanaan pekerjaan fisik infrastruktur secara transparan dari tahun anggaran 2027 hingga 2031 di 14 kecamatan se-Kabupaten Demak.');
INSERT INTO `cms_texts` (`text_key`, `text_value`) VALUES ('map_title', 'Peta Interaktif Perencanaan Wilayah Demak');
INSERT INTO `cms_texts` (`text_key`, `text_value`) VALUES ('map_subtitle', 'Klik pada batas kecamatan di peta untuk memfokuskan wilayah dan menampilkan pin titik pekerjaan. Klik tahun (misal 2027) untuk melihat daftar pekerjaan tahun berjalan.');
INSERT INTO `cms_texts` (`text_key`, `text_value`) VALUES ('map_hint', 'Warna Pin: Biru (Bina Marga Jalan & Jembatan), Hijau/Cyan (SDA BK Air & Bangunan Air), Ungu (Cipta Karya), Kuning Emas (Tata Ruang TRP).');
