INSERT INTO `cms_texts` (`text_key`, `text_value`) VALUES ('bidang_bm_desc', 'Menangani penyelenggaraan jaringan jalan kabupaten, pemeliharaan berkala, rekonstruksi rigid beton/aspal, dan jembatan.');
INSERT INTO `cms_texts` (`text_key`, `text_value`) VALUES ('bidang_sda_desc', 'Mengelola sumber daya air, rumah pompa banjir rob, normalisasi afvour/sungai, embung penampung, pintu air, dan jaringan irigasi.');
INSERT INTO `cms_texts` (`text_key`, `text_value`) VALUES ('bidang_ck_desc', 'Melaksanakan pembangunan sarana gedung negara, penyediaan air minum perpipaan (SPAM), dan sanitasi permukiman.');
INSERT INTO `cms_texts` (`text_key`, `text_value`) VALUES ('bidang_trp_desc', 'Mengawal rencana detail tata ruang (RDTR), rencana tata bangunan dan lingkungan (RTBL), serta tertib pemanfaatan ruang.');
